WITH exploded AS (SELECT id, service, level, status_code, attr_key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, value) SELECT *, ROUND(status_code / SUM(status_code) OVER (PARTITION BY attr_key), 4) AS status_code_share, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share_2, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share_3 FROM exploded WHERE level IN ('ERROR', 'INFO');
